{"content": "import { useEffect, useState } from 'react'
import Navbar from './components/Navbar.jsx'
import Hero from './components/Hero.jsx'
import About from './components/About.jsx'
import Offers from './components/Offers.jsx'
import DownloadCTA from './components/DownloadCTA.jsx'
import Books from './components/Books.jsx'
import Newsletter from './components/Newsletter.jsx'
import Contact from './components/Contact.jsx'
import Footer from './components/Footer.jsx'
import Admin from './components/Admin.jsx'
import { fetchSiteContent } from './lib/admin.js'

export default function App() {
  const [isAdminRoute, setIsAdminRoute] = useState(false)
  const [aboutContent, setAboutContent] = useState(null)

  // Hash routing: '#/admin' renders the admin portal
  useEffect(() => {
    const checkRoute = () => {
      const hash = window.location.hash || ''
      setIsAdminRoute(hash.startsWith('#/admin'))
    }
    checkRoute()
    window.addEventListener('hashchange', checkRoute)
    return () => window.removeEventListener('hashchange', checkRoute)
  }, [])

  // Load editable about content for the public About section
  useEffect(() => {
    fetchSiteContent().then((res) => {
      if (res.data?.about) setAboutContent({ about: res.data.about })
    })
  }, [])

  if (isAdminRoute) return <Admin />

  return (
    <div id="top" className="min-h-screen bg-ink">
      <Navbar />
      <main>
        <Hero />
        <About content={aboutContent} />
        <Offers />
        <DownloadCTA />
        <Books />
        <Newsletter />
        <Contact />
      </main>
      <Footer />
    </div>
  )
}
